import type { MetadataRoute } from 'next';
import { BRAND } from '@/lib/site';

/**
 * The web app manifest: what a phone uses when someone adds the site to the
 * home screen. Colours mirror --bg and --ac in globals.css; a manifest cannot
 * read CSS variables. The icons are generated by `npm run brand`.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: `${BRAND} — Liquidity layer for Robinhood Chain`,
    short_name: BRAND,
    description: 'Deposit into any token on Robinhood Chain and collect swap fees in WETH.',
    start_url: '/pools',
    display: 'standalone',
    background_color: '#ECF2F2',
    theme_color: '#0B6E86',
    icons: [
      { src: '/icons/icon-192.png', sizes: '192x192', type: 'image/png' },
      { src: '/icons/icon-512.png', sizes: '512x512', type: 'image/png' },
      { src: '/icons/icon-1024.png', sizes: '1024x1024', type: 'image/png' },
    ],
  };
}
